/**
 * Maximal 5 Stück pro Produkt im Warenkorb erlauben
 * - begrenzt die Menge beim Hinzufügen
 * - begrenzt die Menge beim Ändern im Warenkorb
 * - erzwingt das Limit vor dem Checkout
 */

//////////////////////
// Grundeinstellung //
//////////////////////

function meine_max_qty_pro_produkt() {
    return 5;
}

/////////////////////////////////////////
// 1) Beim Hinzufügen zum Warenkorb   //
/////////////////////////////////////////

add_filter( 'woocommerce_add_to_cart_validation', 'meine_max_5_pro_produkt_add', 10, 3 );
function meine_max_5_pro_produkt_add( $passed, $product_id, $quantity ) {
    return meine_pruefe_max_5_pro_produkt( $passed, $product_id, $quantity );
}

/////////////////////////////////////////
// 2) Beim Ändern im Warenkorb        //
/////////////////////////////////////////

add_filter( 'woocommerce_update_cart_validation', 'meine_max_5_pro_produkt_update', 10, 4 );
function meine_max_5_pro_produkt_update( $passed, $cart_item_key, $values, $quantity ) {
    $product_id = $values['product_id'];
    return meine_pruefe_max_5_pro_produkt( $passed, $product_id, $quantity, $cart_item_key );
}

/**
 * Gemeinsame Prüf-Funktion für Add-to-Cart & Cart-Update
 */
function meine_pruefe_max_5_pro_produkt( $passed, $product_id, $quantity, $cart_item_key = '' ) {

    $max_qty = meine_max_qty_pro_produkt();
    $current_qty_in_cart = 0;

    if ( WC()->cart ) {
        foreach ( WC()->cart->get_cart() as $key => $cart_item ) {

            $cart_product_id   = isset( $cart_item['product_id'] ) ? (int) $cart_item['product_id'] : 0;
            $cart_variation_id = isset( $cart_item['variation_id'] ) ? (int) $cart_item['variation_id'] : 0;
            $target_product_id = (int) $product_id;

            if ( $cart_product_id === $target_product_id || $cart_variation_id === $target_product_id ) {

                // Beim Update die gerade bearbeitete Zeile nicht doppelt zählen
                if ( $cart_item_key && $cart_item_key === $key ) {
                    continue;
                }

                $current_qty_in_cart += $cart_item['quantity'];
            }
        }
    }

    $new_total = $current_qty_in_cart + $quantity;

    if ( $new_total > $max_qty ) {

        $message = sprintf(
            'Du kannst von diesem Produkt maximal %d Stück in den Warenkorb legen.',
            $max_qty
        );

        if ( ! wc_has_notice( $message, 'error' ) ) {
            wc_add_notice( $message, 'error' );
        }

        return false;
    }

    return $passed;
}

//////////////////////////////////////////////////////////
// 3) Sicherheitsnetz: direkt vor dem Checkout prüfen  //
//////////////////////////////////////////////////////////

add_action( 'woocommerce_check_cart_items', 'meine_max_5_check_cart_items' );
function meine_max_5_check_cart_items() {

    $max_qty = meine_max_qty_pro_produkt();

    if ( ! WC()->cart ) {
        return;
    }

    foreach ( WC()->cart->get_cart() as $cart_item_key => $cart_item ) {
        $qty = isset( $cart_item['quantity'] ) ? (int) $cart_item['quantity'] : 0;

        if ( $qty > $max_qty ) {

            // Menge serverseitig zurücksetzen
            WC()->cart->set_quantity( $cart_item_key, $max_qty, false );

            $product_name = $cart_item['data']->get_name();

            $message = sprintf(
                'Du kannst von "%s" maximal %d Stück bestellen. Die Menge wurde auf %d reduziert.',
                $product_name,
                $max_qty,
                $max_qty
            );

            if ( ! wc_has_notice( $message, 'error' ) ) {
                wc_add_notice( $message, 'error' );
            }
        }
    }
}

/////////////////////////////////////////////////////////////
// 4) (Optional, aber sinnvoll): Maximalwert im Mengenfeld //
/////////////////////////////////////////////////////////////

add_filter( 'woocommerce_quantity_input_args', 'meine_max_5_quantity_input', 10, 2 );
function meine_max_5_quantity_input( $args, $product ) {
    $args['max_value'] = meine_max_qty_pro_produkt();
    return $args;
}

// UncutTV – individuelle Lagerbestandsanzeige für WooCommerce
add_filter( 'woocommerce_get_availability_text', 'uncuttv_custom_stock_message', 10, 2 );

function uncuttv_custom_stock_message( $text, $product ) {

    // Nur eingreifen, wenn WooCommerce den Bestand verwaltet
    if ( ! $product->managing_stock() ) {
        return $text;
    }

    // Aktuelle Menge abfragen
    $qty = $product->get_stock_quantity();

    // Ausverkauft
    if ( $qty <= 0 ) {
        return 'Derzeit ausverkauft';
    }

    // Wenig Bestand (z. B. 10 oder weniger) – MIT genauer Anzahl
    if ( $qty <= 10 ) {
        return sprintf( 'Nur mehr %d Artikel verfügbar', $qty );
    }

    // Genug Bestand: keine Anzeige
    return '';
}

