          '#masthead'
        ];

        let container = null;
        for (const sel of selectors) {
          const el = document.querySelector(sel);
          if (el) { container = el; break; }
        }

        if (!container) {
          const img = document.querySelector('.custom-header img, .wp-custom-header img, #header-media img');
