        const timeEl = badge.querySelector('.cs_cd_time');

        // FIXED: Friday 13.02.2026 18:00 Vienna (CET = +01:00)
        const targetDate = new Date('2026-02-13T18:00:00+01:00');

        function pad(n){ return String(n).padStart(2,'0'); }

        function update(){
          const now = new Date();
          const diff = targetDate - now;

          if (diff <= 0) {
            timeEl.textContent = 'OUT NOW';
            return;
          }

          const totalSeconds = Math.floor(diff / 1000);
          const days = Math.floor(totalSeconds / 86400);
          const hours = Math.floor((totalSeconds % 86400) / 3600);
          const minutes = Math.floor((totalSeconds % 3600) / 60);
          const seconds = totalSeconds % 60;

          timeEl.textContent = `${days}T ${pad(hours)}:${pad(minutes)}:${pad(seconds)}`;

          // subtle glitch every 10 seconds
          if (seconds % 10 === 0) {
            badge.classList.add('cs_glitching');
            setTimeout(() => badge.classList.remove('cs_glitching'), 180);
          }
        }

        update();
        setInterval(update, 1000);
      })();
