    remove_action('woocommerce_before_shop_loop', 'woocommerce_catalog_ordering', 30);
  });

  // 2) Output ONE ALM instance for the current category slug (brandneu, instock, ...)
  add_action('woocommerce_before_shop_loop', function () {

    static $printed = false;
    if ($printed) return;
    $printed = true;

    $term = get_queried_object();
    if ( empty($term) || empty($term->slug) ) return;

    echo '<div id="uncut_al_primary">';

    echo do_shortcode(sprintf(
      '[ajax_load_more post_type="product" posts_per_page="16" scroll="false" button_label="Mehr laden" repeater="default" taxonomy="product_cat" taxonomy_terms="%s" taxonomy_operator="IN" container_type="ul" css_classes="products columns-4" item_type="li" item_classes="product"]',
      esc_attr($term->slug)
    ));

    echo '</div>';

  }, 35);

  /**
   * 3) Frontend cleanup:
   * Remove ANY other product grids / ALM instances that are not inside #uncut_al_primary.
   * This fixes: "under the button another old list appears (instock etc.)"
   */
  add_action('wp_footer', function () { ?>
    <script>
      (function(){
        function cleanup(){
          const primary = document.getElementById('uncut_al_primary');
          if (!primary) return;

          // Remove any extra ALM instances outside our primary wrapper
          document.querySelectorAll('.ajax-load-more-wrap, .ajax-load-more').forEach(el => {
            if (!primary.contains(el)) el.remove();
          });

          // Remove any extra WooCommerce product grids outside our primary wrapper
          // (these are the "old list" under the button)
          document.querySelectorAll('ul.products').forEach(ul => {
            if (!primary.contains(ul)) ul.remove();
          });

          // If there are duplicate "Load more" button wrappers outside primary, remove them
          document.querySelectorAll('.alm-btn-wrap').forEach(btnWrap => {
            if (!primary.contains(btnWrap)) btnWrap.remove();
          });
        }

        // Run after everything is painted (keeps ALM event handlers intact)
        window.addEventListener('load', cleanup);
      })();
