 */
function ghost_create_or_update_member(string $email, string $name = '') {
    if (! defined('GHOST_URL') || ! defined('GHOST_ADMIN_API_KEY')) {
        return new WP_Error('ghost_config', 'Ghost URL oder Admin API Key fehlt.');
    }

    $jwt = ghost_admin_jwt(GHOST_ADMIN_API_KEY);
    if (is_wp_error($jwt)) return $jwt;

    $endpoint = rtrim(GHOST_URL, '/') . '/ghost/api/admin/members/';

    $member = [
        'email'      => $email,
        'subscribed' => true,
    ];

    if ($name !== '') {
        $member['name'] = $name;
    }

    $body = json_encode(['members' => [$member]]);

    $response = wp_remote_post($endpoint, [
        'timeout' => 15,
        'headers' => [
            'Authorization' => 'Ghost ' . $jwt,
            'Content-Type'  => 'application/json',
            'Accept'        => 'application/json',
        ],
        'body' => $body,
    ]);

    if (is_wp_error($response)) return $response;

    $code = (int) wp_remote_retrieve_response_code($response);
    $raw  = (string) wp_remote_retrieve_body($response);

    if ($code >= 200 && $code < 300) {
        return ['ok' => true, 'code' => $code, 'raw' => $raw];
    }

    return ['ok' => false, 'code' => $code, 'error' => $raw];
}

/**
 * Build Ghost Admin API JWT.
 * Admin API key format: "<id>:<secret>"
 */
function ghost_admin_jwt(string $admin_api_key) {
    $parts = explode(':', $admin_api_key, 2);
    if (count($parts) !== 2) {
        return new WP_Error('ghost_key', 'Ghost Admin API Key Format ist falsch. Muss "id:secret" sein.');
    }

    $id     = $parts[0];
    $secret = $parts[1];

    // Ghost secret is base64 url-safe; decode it
    $secret_bin = base64_decode(strtr($secret, '-_', '+/'));
    if ($secret_bin === false) {
        return new WP_Error('ghost_key', 'Ghost Admin API Secret ist nicht korrekt (Base64 decode fehlgeschlagen).');
    }

    $header  = ['alg' => 'HS256', 'typ' => 'JWT', 'kid' => $id];
    $now     = time();
    $payload = ['iat' => $now, 'exp' => $now + 300, 'aud' => '/admin/'];

    $h = ghost_b64url_encode(json_encode($header));
    $p = ghost_b64url_encode(json_encode($payload));

    $sig = hash_hmac('sha256', $h . '.' . $p, $secret_bin, true);

    return $h . '.' . $p . '.' . ghost_b64url_encode($sig);
}

function ghost_b64url_encode(string $data) {
    return rtrim(strtr(base64_encode($data), '+/', '-_'), '=');
}

