/**
 * UncutTV — Force Zero Tax on Reverse Charge Orders
 * 
 * Greift nach REST-API Order-Creation (woocommerce_rest_insert_shop_order_object)
 * UND bei klassischen Saves (woocommerce_new_order).
 * 
 * Setzt alle Steuern auf 0 wenn _uncuttv_reverse_charge = "yes".
 */

function uncuttv_force_zero_tax_on_reverse_charge( $order ) {
    if ( ! $order instanceof WC_Order ) return;

    $reverse_charge = $order->get_meta( '_uncuttv_reverse_charge' );
    if ( $reverse_charge !== 'yes' ) return;

    // Line Items: Steuer auf 0
    foreach ( $order->get_items() as $item_id => $item ) {
        $item->set_taxes( [
            'subtotal' => [],
            'total'    => [],
        ] );
        $item->save();
    }

    // Shipping Lines: Steuer auf 0
    foreach ( $order->get_items( 'shipping' ) as $shipping_id => $shipping ) {
        $shipping->set_taxes( [ 'total' => [] ] );
        $shipping->save();
    }

    // Fee Lines: Steuer auf 0
    foreach ( $order->get_items( 'fee' ) as $fee_id => $fee ) {
        $fee->set_taxes( [ 'total' => [] ] );
        $fee->save();
    }

    // Tax Lines entfernen
    foreach ( $order->get_items( 'tax' ) as $tax_id => $tax_line ) {
        $order->remove_item( $tax_id );
    }

    // Order-Level: Tax-Felder auf 0
    $order->set_cart_tax( 0 );
    $order->set_shipping_tax( 0 );

    // Total recalc manuell (Subtotal + Shipping - Discount, OHNE Tax)
    $new_total = floatval( $order->get_subtotal() ) 
               + floatval( $order->get_shipping_total() ) 
               - floatval( $order->get_total_discount() );

    $order->set_total( $new_total );
    $order->save();
}

// Hook 1: REST API Order Creation (das ist unser Hauptfall)
add_action( 'woocommerce_rest_insert_shop_order_object', function( $order, $request, $creating ) {
    uncuttv_force_zero_tax_on_reverse_charge( $order );
}, 999, 3 );

// Hook 2: Klassischer New Order (für Sicherheit, falls jemand manuell anlegt)
add_action( 'woocommerce_new_order', function( $order_id ) {
    $order = wc_get_order( $order_id );
    uncuttv_force_zero_tax_on_reverse_charge( $order );
}, 999, 1 );

function uncuttv_force_zero_tax_on_third_country( $order ) {
    if ( ! $order instanceof WC_Order ) return;
    if ( $order->get_meta( '_uncuttv_third_country' ) !== 'yes' ) return;

    foreach ( $order->get_items() as $item ) {
        $item->set_taxes( [ 'subtotal' => [], 'total' => [] ] );
        $item->save();
    }
    foreach ( $order->get_items( 'shipping' ) as $shipping ) {
        $shipping->set_taxes( [ 'total' => [] ] );
        $shipping->save();
    }
    foreach ( $order->get_items( 'fee' ) as $fee ) {
        $fee->set_taxes( [ 'total' => [] ] );
        $fee->save();
    }
    foreach ( $order->get_items( 'tax' ) as $tax_id => $tax_line ) {
        $order->remove_item( $tax_id );
    }
    $order->set_cart_tax( 0 );
    $order->set_shipping_tax( 0 );
    $new_total = floatval( $order->get_subtotal() ) 
               + floatval( $order->get_shipping_total() ) 
               - floatval( $order->get_total_discount() );
    $order->set_total( $new_total );
    $order->save();
}
add_action( 'woocommerce_rest_insert_shop_order_object', function( $order, $request, $creating ) {
    uncuttv_force_zero_tax_on_third_country( $order );
}, 999, 3 );
add_action( 'woocommerce_new_order', function( $order_id ) {
    uncuttv_force_zero_tax_on_third_country( wc_get_order( $order_id ) );
}, 999, 1 );
